  "claim": {
    "component_id": "C056.main",
    "value": "Causal interpretation should stop if the referenced checks fail or the evidence is too sparse.",
    "scope": "Either condition triggers the restriction. The exact set of referenced checks is ambiguous; nearby linkage and capture checks are a plausible antecedent, but no exhaustive set is supplied.",
    "provenance": {
