          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P027 states the conditional restriction; P025 supplies nearby context for the unresolved reference to checks."
    }
  },
  "signal_basis": {
    "component_id": "C056.signal_basis",
    "value": "Evaluation finds that the referenced checks fail or that evidence is too sparse to sustain causal interpretation. Relevant concerns include linkage and capture comparability, small cohorts, incomplete follow-up, comparison-group differences and concurrent changes.",
    "scope": "Assessment of the release effect; these concerns contextualize the trigger without establishing an exhaustive definition of the referenced checks.",
    "provenance": {
      "refs": [
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
